      nguyen:{country:"Việt Nam · Đại Nam",capital:"Huế",emblem:"Kim bảo · ngọc tỷ · triều ấn",flag:"Có nhiều loại cờ theo nghi lễ và giai đoạn",note:"Cần ghi rõ niên đại từng lá cờ, không dùng một mẫu cho toàn triều."}
